fields.InputDefinition:
{
  "goal": "Open the AI app via the application switcher dropdown next to the logo (NOT Ctrl+K), open the MCP section, and go to the Servers tab. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) server-card-expand — if any server cards are shown, click a server card header (the chevron/name area) to expand it and confirm it reveals the server's detail grid (Transport, Auth, Connections, Tools) and an 'Available Tools' section listing tools or a 'No tools discovered yet' message; if no servers are configured, a 'No MCP servers configured' empty state is acceptable; (2) add-server-transport — click 'Add Server' (or 'Add Your First Server') to open the Add MCP Server dialog, then change the 'Transport Type' dropdown and confirm the form adapts: an HTTP-based transport (Streamable HTTP / SSE / WebSocket) reveals a 'Server URL' field while 'Standard I/O' reveals a 'Command' field instead. You do NOT need to save a server. Keep going until both sections are done. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200/app/ai",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "server-card-expand",
      "instruction": "expand a server card to reveal its tools",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/ai"
        }
      ],
      "visualCriteria": [
        "The Servers tab shows server cards (or a valid 'No MCP servers configured' empty state); clicking a server card header expands it to show detail fields (Transport, Auth, Connections, Tools) and an 'Available Tools' section, and the expand arrow/state visibly toggles"
      ]
    },
    {
      "name": "add-server-transport",
      "instruction": "Add Server dialog conditional transport fields",
      "visualCriteria": [
        "The Add MCP Server dialog opens with Name, Description, Transport Type, and Status fields; selecting an HTTP transport (Streamable HTTP/SSE/WebSocket) shows a 'Server URL' input while selecting 'Standard I/O' shows a 'Command' input instead, and the conditional field visibly changes when the Transport Type value changes"
      ]
    }
  ]
}
